import os, re
from collections import defaultdict

STORE_ROOT = "store"
# Primary persistent entity types (exported row structs in store/*.go root)
ENTITY_TYPES = [
    "User", "Memo", "Attachment", "Inbox", "IdentityProvider",
    "InstanceSetting", "MemoRelation", "MemoShare", "Reaction",
    "UserIdentity", "UserSetting", "AuthenticationConfigState",
]

def is_outside_store(path):
    norm = path.replace("\\", "/")
    if norm.startswith("./"):
        norm = norm[2:]
    return not (norm == "store" or norm.startswith("store/"))

def get_package(path):
    return os.path.dirname(path.replace("\\", "/"))

def scan_go_files():
    for root, dirs, files in os.walk("."):
        dirs[:] = [d for d in dirs if d not in (".git", "node_modules", "web")]
        for f in files:
            if f.endswith(".go"):
                yield os.path.join(root, f).replace("\\", "/").lstrip("./")

# Pattern: store.Type as qualified reference
type_patterns = {t: re.compile(r'\bstore\.' + re.escape(t) + r'\b') for t in ENTITY_TYPES}
# Also: imported store package and bare Type in files that import store
import_pattern = re.compile(r'"github\.com/usememos/memos/store"')

results = {t: set() for t in ENTITY_TYPES}

for filepath in scan_go_files():
    if not is_outside_store(filepath):
        continue
    try:
        content = open(filepath, encoding="utf-8").errors("replace").read()
    except OSError:
        continue
    pkg = get_package(filepath)
    has_store_import = bool(import_pattern.search(content))
    for t, pat in type_patterns.items():
        if pat.search(content):
            results[t].add(pkg)
    # bare references when file imports store (less common but check)
    if has_store_import:
        for t in ENTITY_TYPES:
            bare = re.compile(r'(?<!\.)\b' + re.escape(t) + r'\b')
            if bare.search(content) and not type_patterns[t].search(content):
                # could be false positive from other packages; skip unless clearly entity
                pass

for t in ENTITY_TYPES:
    pkgs = sorted(results[t])
    if pkgs:
        print(f"{t}: {len(pkgs)}")
        for p in pkgs:
            print(f"  {p}")
        print()
