package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

var entityTypes = []string{
	"User", "Memo", "Attachment", "Inbox", "IdentityProvider",
	"InstanceSetting", "MemoRelation", "MemoShare", "Reaction",
	"UserIdentity", "UserSetting", "AuthenticationConfigState",
}

func isOutsideStore(path string) bool {
	path = filepath.ToSlash(path)
	return !(path == "store" || strings.HasPrefix(path, "store/"))
}

func main() {
	results := make(map[string]map[string]struct{})
	for _, t := range entityTypes {
		results[t] = make(map[string]struct{})
	}

	fset := token.NewFileSet()
	filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			if info != nil && info.IsDir() {
				base := filepath.Base(path)
				if base == ".git" || base == "node_modules" || base == "web" {
					return filepath.SkipDir
				}
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") || !isOutsideStore(path) {
			return nil
		}
		pkgDir := filepath.ToSlash(filepath.Dir(path))
		f, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil
		}
		ast.Inspect(f, func(n ast.Node) bool {
			se, ok := n.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			id, ok := se.X.(*ast.Ident)
			if !ok || id.Name != "store" {
				return true
			}
			for _, t := range entityTypes {
				if se.Sel.Name == t {
					results[t][pkgDir] = struct{}{}
				}
			}
			return true
		})
		return nil
	})

	type row struct {
		name  string
		count int
		pkgs  []string
	}
	var rows []row
	for _, t := range entityTypes {
		pkgs := make([]string, 0, len(results[t]))
		for p := range results[t] {
			pkgs = append(pkgs, p)
		}
		sort.Strings(pkgs)
		rows = append(rows, row{t, len(pkgs), pkgs})
	}
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].count != rows[j].count {
			return rows[i].count > rows[j].count
		}
		return rows[i].name < rows[j].name
	})
	for _, r := range rows {
		fmt.Printf("%s: %d\n", r.name, r.count)
		for _, p := range r.pkgs {
			fmt.Printf("  %s\n", p)
		}
		fmt.Println()
	}
}
GOEOF
